    expect(response.status).toBe(403);

    const body = await response.json() as Record<string, unknown>;
    expect(body.error).toBe("policy_violation");
    expect(body.policy_ref).toBeDefined();
    expect(body.remediation).toBeDefined();
  }, 15_000);
});

