     1→/**
     2→ * Regorus WASM loader and Rego compilation interface.
     3→ *
     4→ * WASM loading strategy:
     5→ * - Synchronous CJS require() via wasm-bindgen nodejs target
     6→ * - Module-level promise for idempotent lazy init (safe for concurrent calls)
     7→ * - Fail-closed: WASM load failure throws; callers catch to return deny
     8→ */
     9→
    10→import type { IntentEvaluationContext } from "./types";
    11→
    12→export type CompileError = {
    13→  line: number;
    14→  column: number;
    15→  message: string;
    16→};
    17→
    18→export type CompileResult =
    19→  | { success: true }
    20→  | { success: false; errors: CompileError[] };
    21→
    22→export type RegoEvaluationResult = {
    23→  decision: "allow" | "deny";
    24→  messages: string[];
    25→  evidence_requirement?: { min_count: number; required_types?: string[] };
    26→};
    27→
    28→// ---------------------------------------------------------------------------
    29→// WASM module type (subset of Regorus JS bindings)
    30→// ---------------------------------------------------------------------------
    31→
    32→type RegorusModule = {
    33→  Engine: new () => RegorusEngine;
    34→};
    35→
    36→type RegorusEngine = {
    37→  addPolicy(path: string, rego: string): string;
    38→  setInputJson(input: string): void;
    39→  evalQuery(query: string): string;
    40→  getPackages(): string[];
    41→  free(): void;
    42→};
    43→
    44→// ---------------------------------------------------------------------------
    45→// evalQuery result shape
    46→// ---------------------------------------------------------------------------
    47→
    48→type EvalQueryResult = {
    49→  result?: Array<{
    50→    expressions: Array<{
    51→      value: unknown;
    52→    }>;
    53→  }>;
    54→};
    55→
    56→// ---------------------------------------------------------------------------
    57→// Module-level idempotent WASM init promise
    58→// Prohibited: module-level mutable singletons (AGENTS.md)
    59→// Allowed: module-level promise is idempotent — concurrent calls share the
    60→// same promise and all await the same result.
    61→// ---------------------------------------------------------------------------
    62→
    63→const regorusModulePromise: Promise<RegorusModule> = (async () => {
    64→  // require() is synchronous; wrapped in promise for uniform async interface
    65→  // eslint-disable-next-line @typescript-eslint/no-require-imports
    66→  const mod = require("../../../../vendor/regorus-wasm/regorusjs") as RegorusModule;
    67→  if (typeof mod.Engine !== "function") {
    68→    throw new Error("Regorus WASM failed to load: Engine class not found");
    69→  }
    70→  return mod;
    71→})();
    72→
    73→// ---------------------------------------------------------------------------
    74→// Error parsing
    75→// ---------------------------------------------------------------------------
    76→
    77→/**
    78→ * Parse the Regorus error string format into structured CompileError objects.
    79→ *
    80→ * Format example:
    81→ *   \n--> test.rego:2:18\n  |\n2 | default allow := !!!\n  |  ^\nerror: invalid character
    82→ *
    83→ * The location header pattern: `--> <file>:<line>:<column>`
    84→ * The error message follows on the last line: `error: <message>`
    85→ */
    86→const parseRegorusErrorString = (errorString: string): CompileError[] => {
    87→  const lines = errorString.split("\n");
    88→  const errors: CompileError[] = [];
    89→
    90→  let currentLine: number | undefined;
    91→  let currentColumn: number | undefined;
    92→
    93→  for (const line of lines) {
